/*
	Sunrise, 
	inspired by Remistura Studio: https://twitter.com/remistura/status/1669133411242352642?s=46&t=HTRhiSpU33hsz7dxzN55HQ
	docu: https://developer.mozilla.org/en-US/docs/Web/API/CanvasRenderingContext2D/createRadialGradient
*/

let wh, angle;

function setup() {
	// createCanvas(wh = max(windowWidth, windowHeight), wh);
	wh = max(windowWidth, windowHeight)
	createCanvas(windowWidth, windowHeight);
	angle = 0;
}

function windowResized() {
	setup();
}

function draw() {
	background(0, 0, 12, 96); // some alpha for motion blur
	noStroke();

	const wh2 = wh * 0.5;
	const delta = sin(frameCount * 0.03) * 4;
	const dx = map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, -wh2, wh2) * 0.25;
	const dy = map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, -wh2, wh2) * 0.25;
	translate(width*0.5, height*0.5);
	const gradient = drawingContext.
		createRadialGradient(dx, dy, wh2*0.5+delta*8, dx, dy, wh2 * 0.95);
	gradient.addColorStop(0, "yellow");
	gradient.addColorStop(0.5, "orange");
	gradient.addColorStop(1, "purple");
	drawingContext.fillStyle = gradient;

	const r = wh2 * 0.75;
	const x = cos(angle) * r ;
	const y = sin(angle) * r ;
	circle(x, y, wh2 * 0.4);
	angle += 0.02;

	fill("yellow");
	translate(dx, dy);
	circle(0, 0, wh2 * 0.1 + delta);
	stroke(255, 64)
	drawingContext.setLineDash([10 + delta, 10 - delta * 0.5]);
	for (let i = 0; i < 27; i++) {
		line(-wh, 0, wh, 0);
		rotate(TWO_PI/27);
	}
}
